<section id="executive">
  <div class="container">
    <div class="section-label">Section 01</div>
    <h2 class="section-title">Executive Overview</h2>
    <p class="section-desc">AXP has delivered exceptional compounding wealth over more than five decades, transforming a $1.22 split-adjusted share into a $306 asset — a journey punctuated by severe bear markets and powerful recoveries.</p>

    <!-- KPI DASHBOARD -->
    <div class="kpi-grid">
      <div class="kpi-card blue">
        <div class="kpi-label">Cumulative Total Return</div>
        <div class="kpi-value">24,895%</div>
